SELECT COALESCE(SUM(view_count), 0)
FROM page_view_daily
WHERE view_date = #{viewDate}

SELECT path, SUM(view_count) AS viewCount
FROM page_view_daily
WHERE view_date >= #{startDate, jdbcType=DATE}
    AND view_date  <= #{endDate, jdbcType=DATE}
GROUP BY path
ORDER BY SUM(view_count) DESC, path ASC

SELECT COALESCE(SUM(view_count), 0)
FROM page_view_daily
WHERE view_date >= #{startDate, jdbcType=DATE}
AND view_date <= #{endDate, jdbcType=DATE}
